SELECT CAST(SUM(CASE WHEN v.Venue_Name = 'M Chinnaswamy Stadium' THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN v.Venue_Name = 'Maharashtra Cricket Association Stadium' THEN 1 ELSE 0 END) AS difference
FROM Match m
JOIN Venue v ON m.Venue_Id = v.Venue_Id;

SELECT COUNT(DISTINCT Match_Id) AS match_count
FROM Ball_by_Ball
WHERE Innings_No = 2;

SELECT COUNT(*) AS EmployeeCount
FROM EmployeePayHistory
WHERE PayFrequency = 1 AND Rate > 50;

SELECT Vendor.Name, Vendor.AccountNumber 
FROM Vendor 
WHERE Vendor.CreditRating = 5;

SELECT COUNT(*) AS EmployeeCount
FROM Employee
WHERE MaritalStatus = 'S';

SELECT MIN(SafetyStockLevel) AS MinInventoryQuantity
FROM Product
WHERE LOWER(Name) LIKE '%chainring%';

SELECT COUNT(*) AS Mr_Count
FROM Person
WHERE PersonType = 'SC' AND Title = 'Mr.';

SELECT e.Service * e.GDP AS Service_of_GDP
FROM economy e
WHERE LOWER(e.Country) = 'brazil';

SELECT Country, Population AS "Population", Population_Growth AS "Growth"
FROM population
WHERE Population_Growth < 0;

SELECT Country1, Country2
FROM borders
WHERE Length = 803;

SELECT Country, Name AS Language, Percentage
FROM language
WHERE LOWER(Country) = LOWER('english') OR (Percentage = 100 AND Name = 'English');

SELECT Name, Longitude, Latitude
FROM desert
WHERE Area > 0;
